import{_ as s,C as d,o as i,c,aj as o,E as r,j as a,a as n}from"./framework.js";const v=JSON.parse('{"title":"AI Service | Settings | Admin CMS","description":"AI Service configures site-level AI capabilities: vector search, MCP server, AI functions, llms.txt, automatic Markdown output, and global JSON-LD mapping. It appears under both Settings…","frontmatter":{"title":"AI Service | Settings | Admin CMS","description":"AI Service configures site-level AI capabilities: vector search, MCP server, AI functions, llms.txt, automatic Markdown output, and global JSON-LD mapping. It appears under both Settings…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/settings/ai-service.html"}]]},"headers":[],"relativePath":"cms/settings/ai-service.md","filePath":"en/cms/settings/ai-service.md","lastUpdated":1781010536000}'),l={name:"cms/settings/ai-service.md"};function g(h,t,p,m,u,b){const e=d("DocImage");return i(),c("div",null,[t[0]||(t[0]=o('<h1 id="ai-service" tabindex="-1">AI Service <a class="header-anchor" href="#ai-service" aria-label="Permalink to &quot;AI Service&quot;">​</a></h1><blockquote><p>Menu: <strong>Settings -&gt; AI Service</strong> (advanced menu) Same page from: <strong>Operations Center -&gt; AI Service</strong> Deep link: <code>/_Admin/system/ai-service?SiteId={siteGuid}</code> Tab deep links: <code>name=settings</code> / <code>functions</code> / <code>vectorSearch</code> / <code>llms</code> / <code>markdown</code> / <code>jsonld</code></p></blockquote><p><strong>AI Service</strong> configures site-level AI capabilities: vector search, MCP server, AI functions, <code>llms.txt</code>, automatic Markdown output, and global JSON-LD mapping. It appears under both <strong>Settings</strong> and <strong>Operations Center</strong> but is the <strong>same page</strong>; this doc is the single source of truth.</p><div class="tip custom-block"><p class="custom-block-title">Permissions</p><table tabindex="0"><thead><tr><th>Action</th><th>Permission</th></tr></thead><tbody><tr><td>Open <strong>AI Service</strong></td><td><code>ai</code></td></tr><tr><td>View custom AI function list</td><td><code>ai·view</code></td></tr><tr><td>Add, edit, delete AI functions</td><td>UI checks <code>mcp·edit</code>; backend <code>mcp/PostTool</code>, <code>mcp/DeleteTools</code> check <code>ai·edit</code></td></tr><tr><td>Run custom AI functions</td><td>UI checks <code>mcp·view</code></td></tr><tr><td>Save <strong>MCP Service</strong> and <strong>Vector Search</strong> settings</td><td>Bottom save checks <code>mcp·edit</code> and saves site AI settings</td></tr><tr><td>Save <code>llms.txt</code>, Markdown, JSON-LD config</td><td>Requires access to this page; Markdown / JSON-LD toggles save site AI settings</td></tr></tbody></table></div><div class="info custom-block"><p class="custom-block-title">Scope</p><p>Tabs with UI and server APIs today: <strong>MCP / AI Functions</strong>, <strong>llms.txt Generator</strong>, <strong>Automatic Markdown Engine</strong>, <strong>Global JSON-LD Mapping</strong>. Pay-per-crawl is not exposed in the UI and is omitted here.</p></div><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In <a href="./../navigation.html#permissions-and-edit-menu">Edit Menu</a>, enable <strong>Settings -&gt; AI Service</strong> or <strong>Operations Center -&gt; AI Service</strong>.</li><li>Open the matching left menu item. Both go to <code>/_Admin/system/ai-service</code>.</li></ol>',7)),r(e,{src:"/cms/settings/settings-ai-service-overview.png",alt:"AI Service settings page",width:"1120"}),t[1]||(t[1]=a("h2",{id:"page-structure",tabindex:"-1"},[n("Page Structure "),a("a",{class:"header-anchor",href:"#page-structure","aria-label":'Permalink to "Page Structure"'},"​")],-1)),t[2]||(t[2]=a("p",null,[n("Tabs update the URL "),a("code",null,"name"),n(" parameter when switched.")],-1)),r(e,{src:"/cms/settings/settings-ai-service-tabs.png",alt:"AI Service tabs",width:"1120"}),t[3]||(t[3]=o('<table tabindex="0"><thead><tr><th>Tab</th><th>Purpose</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Settings</strong></td><td>Enable vector search, pick Embedding Provider / Model, enable MCP service</td><td>Default tab</td></tr><tr><td><strong>AI Functions</strong></td><td>Manage custom functions, view built-ins, trial-run custom functions</td><td>Writes to site <code>AIFunction</code> store</td></tr><tr><td><strong>Vector Search</strong></td><td>Index status by object type, sync or rebuild</td><td>Shown only after vector search is enabled under <strong>Settings</strong></td></tr><tr><td><strong>llms.txt Generator</strong></td><td>Generate, edit, save site root <code>/llms.txt</code></td><td>Builds index from live pages</td></tr><tr><td><strong>Automatic Markdown Engine</strong></td><td>Enable <code>.md</code> route output and override rules</td><td>Saves site <code>AI.MarkdownEngine</code></td></tr><tr><td><strong>Global JSON-LD Mapping</strong></td><td>Map content / database fields to Schema.org properties</td><td>Saves site <code>AI.JsonLD</code> and mappings</td></tr></tbody></table><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Configure underlying capabilities here before using other tabs.</p>',3)),r(e,{src:"/cms/settings/settings-ai-service-settings.png",alt:"AI Service Settings tab",width:"1120"}),t[4]||(t[4]=o('<h3 id="vector-search" tabindex="-1">Vector Search <a class="header-anchor" href="#vector-search" aria-label="Permalink to &quot;Vector Search&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Description</th></tr></thead><tbody><tr><td><strong>Enable vector search</strong></td><td>Saves <code>ai.vectorSearch.enable</code>; shows <strong>Vector Search</strong> tab</td></tr><tr><td><strong>Provider</strong></td><td>AI Provider that supports Embedding Models; if empty, check org-level AI Providers</td></tr><tr><td><strong>Model</strong></td><td>Embedding model for that Provider; switching Provider picks the first available model</td></tr></tbody></table><p>After save, new/updated content is indexed per vector search rules; run <strong>sync</strong> or <strong>rebuild</strong> on <a href="#vector-search">Vector Search</a> for existing objects.</p><h3 id="mcp-service" tabindex="-1">MCP Service <a class="header-anchor" href="#mcp-service" aria-label="Permalink to &quot;MCP Service&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Description</th></tr></thead><tbody><tr><td><strong>Enable MCP service</strong></td><td>Enables site MCP Server for external MCP clients</td></tr><tr><td><strong>Development Connection Information</strong></td><td>On non-production servers: <code>Endpoint</code> and <code>Authorization Header</code></td></tr><tr><td><strong>Disable built-in AI tools</strong></td><td>Hides system tools; only user-created AI functions are exposed</td></tr></tbody></table><p><code>Endpoint</code> is derived from site <a href="./basic/general.html#site-information">Base URL</a> with <code>_mcp</code> appended; <code>http</code> Base URLs are shown as <code>https</code> in the UI. The Bearer token in dev connection is the current login credential—debug only; do not put it in docs, screenshots, or repos.</p><h2 id="ai-functions" tabindex="-1">AI Functions <a class="header-anchor" href="#ai-functions" aria-label="Permalink to &quot;AI Functions&quot;">​</a></h2><p>The <strong>AI Functions</strong> tab has <strong>Custom</strong> and <strong>Built-in</strong> sections. Custom functions can be exposed via MCP and called from site AI; built-ins are system-provided (name and description only).</p>',8)),r(e,{src:"/cms/settings/settings-ai-service-functions.png",alt:"AI Functions custom list",width:"1120"}),t[5]||(t[5]=o('<p>Without <code>mcp·edit</code>, <strong>Add Tool</strong> is disabled; assign permissions in <a href="./roles.html">Roles</a> first.</p><h3 id="custom-list" tabindex="-1">Custom List <a class="header-anchor" href="#custom-list" aria-label="Permalink to &quot;Custom List&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control / column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Add Tool</strong></td><td>Opens <a href="#ai-tool-dialog">AI tool dialog</a></td></tr><tr><td><strong>Custom / Built-in</strong></td><td>Toggle list in the top-right</td></tr><tr><td><strong>Name</strong></td><td>Custom tool name; avoid renaming after first save</td></tr><tr><td><strong>Tags</strong></td><td>From <code>mcp/FunctionTags</code>; used for categorization and discovery</td></tr><tr><td><strong>Description</strong></td><td>Natural language for AI / callers</td></tr><tr><td><strong>Run</strong></td><td>Shown when exactly one row is selected; opens params and result dialog</td></tr><tr><td><strong>Edit / Delete</strong></td><td>Edit tool or multi-select delete</td></tr></tbody></table><h3 id="ai-tool-dialog" tabindex="-1">AI Tool Dialog <a class="header-anchor" href="#ai-tool-dialog" aria-label="Permalink to &quot;AI Tool Dialog&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Required on create, unique, 1–50 chars; disabled when editing</td></tr><tr><td><strong>Description</strong></td><td>What it solves, when to call, what it returns</td></tr><tr><td><strong>Tags</strong></td><td>Multi-select for discovery</td></tr><tr><td><strong>Execution code</strong></td><td>Monaco TypeScript with KScript mode; API details in related links</td></tr><tr><td><strong>Input Schema</strong></td><td>JSON Schema for run parameters; run dialog generates sample input</td></tr></tbody></table><p>Description and Input Schema affect call quality more than code. Define <strong>boundaries, required params, and return shape</strong> before code; never hardcode secrets, external tokens, or long-lived credentials.</p><h3 id="run-check" tabindex="-1">Run Check <a class="header-anchor" href="#run-check" aria-label="Permalink to &quot;Run Check&quot;">​</a></h3><p><strong>Run</strong> reads Input Schema and builds JSON parameters. Adjust and <strong>Run</strong>; backend calls <code>mcp/RunTool</code> and shows the result. If Schema has no properties, the dialog runs immediately and shows results.</p><h3 id="built-in-tools" tabindex="-1">Built-in Tools <a class="header-anchor" href="#built-in-tools" aria-label="Permalink to &quot;Built-in Tools&quot;">​</a></h3>',9)),r(e,{src:"/cms/settings/settings-ai-service-built-in-tools.png",alt:"AI Functions built-in list",width:"1120"}),t[6]||(t[6]=o('<p>Built-ins list <strong>Name</strong> and <strong>Description</strong> only. To block MCP clients from built-ins, enable <strong>Disable built-in AI tools</strong> under <a href="#mcp-service">Settings</a>.</p><h2 id="vector-search-1" tabindex="-1">Vector Search <a class="header-anchor" href="#vector-search-1" aria-label="Permalink to &quot;Vector Search&quot;">​</a></h2><p>The <strong>Vector Search</strong> tab appears only after <strong>Settings -&gt; Enable vector search</strong> is saved. Lists index status by object type.</p><table tabindex="0"><thead><tr><th>Column / action</th><th>Description</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Object type: product, page, view, content, etc.</td></tr><tr><td><strong>Total</strong></td><td>Count of indexable objects</td></tr><tr><td><strong>Unsynced</strong></td><td>No vector yet, or object updated / model mismatch</td></tr><tr><td><strong>Queued</strong></td><td>Submitted but incomplete index jobs</td></tr><tr><td><strong>Status</strong></td><td>Running, error, pending sync, or complete</td></tr><tr><td><strong>Sync</strong></td><td>Process unsynced items for selected types</td></tr><tr><td><strong>Rebuild</strong></td><td>Delete existing vectors for selected types and re-index all</td></tr></tbody></table><p>After changing Embedding Provider or Model, <strong>Rebuild</strong> key object types when models no longer match.</p><h2 id="llms-txt-generator" tabindex="-1">llms.txt Generator <a class="header-anchor" href="#llms-txt-generator" aria-label="Permalink to &quot;llms.txt Generator&quot;">​</a></h2><p><code>llms.txt</code> gives AI crawlers a site content index. The admin reads and saves <code>/llms.txt</code>.</p>',7)),r(e,{src:"/cms/settings/settings-ai-service-llms.png",alt:"llms.txt generator",width:"1120"}),t[7]||(t[7]=o('<table tabindex="0"><thead><tr><th>Control</th><th>Description</th></tr></thead><tbody><tr><td><strong>Generate</strong></td><td>Draft <code>llms.txt</code> from live pages; each page links to its <code>.md</code> URL</td></tr><tr><td><strong>Text area</strong></td><td>Manual edit of final content</td></tr><tr><td><strong>Save</strong></td><td>Writes text area to root <code>/llms.txt</code></td></tr></tbody></table><p>Before generating, confirm pages are live, routes are correct, and <a href="#automatic-markdown-engine">Automatic Markdown Engine</a> is enabled if you want <code>.md</code> links to work for AI clients.</p><h2 id="automatic-markdown-engine" tabindex="-1">Automatic Markdown Engine <a class="header-anchor" href="#automatic-markdown-engine" aria-label="Permalink to &quot;Automatic Markdown Engine&quot;">​</a></h2><p>When enabled, appending <code>.md</code> or <code>index.html.md</code> to a page path finds the original route and converts rendered HTML to Markdown.</p>',4)),r(e,{src:"/cms/settings/settings-ai-service-markdown.png",alt:"Automatic Markdown engine",width:"1120"}),t[8]||(t[8]=o('<h3 id="enable-toggle" tabindex="-1">Enable Toggle <a class="header-anchor" href="#enable-toggle" aria-label="Permalink to &quot;Enable Toggle&quot;">​</a></h3><p>Top-right <strong>Enable</strong> saves <code>AI.MarkdownEngine.Enable</code> immediately. When off, <code>.md</code> routes are not rendered as Markdown.</p><h3 id="override-rules" tabindex="-1">Override Rules <a class="header-anchor" href="#override-rules" aria-label="Permalink to &quot;Override Rules&quot;">​</a></h3><p>Override rules assign objects or disable rules for specific paths.</p>',4)),r(e,{src:"/cms/settings/settings-ai-service-markdown-rule-dialog.png",alt:"Markdown override rule dialog",width:"1120"}),t[9]||(t[9]=o('<table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Match path</strong></td><td>Front-end path to override; use real URLs to match page routes</td></tr><tr><td><strong>Applicable object</strong></td><td>Object id for that path</td></tr><tr><td><strong>Status</strong></td><td>Enable or disable the override</td></tr></tbody></table><p>Add, edit, delete rules update the form only; click bottom <strong>Save</strong> to persist to the site.</p><h2 id="global-json-ld-mapping" tabindex="-1">Global JSON-LD Mapping <a class="header-anchor" href="#global-json-ld-mapping" aria-label="Permalink to &quot;Global JSON-LD Mapping&quot;">​</a></h2><p>Maps Kooboo content or database fields to Schema.org types and properties. When enabled, pages emit <code>application/ld+json</code> structured data.</p>',4)),r(e,{src:"/cms/settings/settings-ai-service-jsonld.png",alt:"Global JSON-LD mapping",width:"1120"}),t[10]||(t[10]=o('<h3 id="enable-toggle-1" tabindex="-1">Enable Toggle <a class="header-anchor" href="#enable-toggle-1" aria-label="Permalink to &quot;Enable Toggle&quot;">​</a></h3><p>Top-right <strong>Enable</strong> saves <code>AI.JsonLD.Enable</code>. Complete at least one data source mapping before enabling on production.</p><h3 id="data-sources-and-field-mapping" tabindex="-1">Data Sources and Field Mapping <a class="header-anchor" href="#data-sources-and-field-mapping" aria-label="Permalink to &quot;Data Sources and Field Mapping&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Area</th><th>Description</th></tr></thead><tbody><tr><td><strong>Kooboo data source</strong></td><td><code>content</code>, <code>indexeddb</code>, <code>sqlite</code>, <code>mysql</code>, <code>sqlserver</code>, <code>mongo</code>, etc.</td></tr><tr><td><strong>Data</strong></td><td>Content folder or table</td></tr><tr><td><strong>Schema type</strong></td><td>From Schema.org tree: Article, Product, Organization, etc.</td></tr><tr><td><strong>Kooboo variable/field</strong></td><td>Fields from the data source</td></tr><tr><td><strong>Schema property</strong></td><td>Schema.org property per field</td></tr></tbody></table><p>Content fields come from <a href="./../content/content-types.html">Content Types</a>; database fields come from table structure. If expected fields are missing, verify models in Content or Database first.</p><h2 id="typical-workflow" tabindex="-1">Typical Workflow <a class="header-anchor" href="#typical-workflow" aria-label="Permalink to &quot;Typical Workflow&quot;">​</a></h2><ol><li>Confirm site <a href="./basic/general.html#site-information">Base URL</a> and AI Provider / Embedding model availability.</li><li>Under <strong>Settings</strong>, enable <strong>MCP service</strong> and/or <strong>vector search</strong>; save.</li><li>Under <strong>AI Functions</strong>, create tools: name, description, tags, Input Schema, then code and <strong>Run</strong> to verify.</li><li>If vector search is on, <strong>Sync</strong> or <strong>Rebuild</strong> on the <strong>Vector Search</strong> tab.</li><li>For AI crawlers: enable <strong>Automatic Markdown Engine</strong>, then generate and save <code>/llms.txt</code>.</li><li>For structured data: prepare fields in content types or tables, then map in <strong>Global JSON-LD Mapping</strong>.</li></ol><h2 id="cms-vs-api-template-engine" tabindex="-1">CMS vs API / Template Engine <a class="header-anchor" href="#cms-vs-api-template-engine" aria-label="Permalink to &quot;CMS vs API / Template Engine&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>CMS</th><th>API / Template Engine</th></tr></thead><tbody><tr><td>Enable MCP, copy dev connection info</td><td><strong>Settings</strong> on this page</td><td>—</td></tr><tr><td>Create AI functions, descriptions, Input Schema</td><td><strong>AI Functions</strong> on this page</td><td><a href="./../development/code.html">Development -&gt; Code</a>, <a href="/kb-docs/api/site/code.html">k.site Code API</a>, <a href="/kb-docs/api/">KScript API</a></td></tr><tr><td>Read content, database, commerce in functions</td><td>Function entry only on this page</td><td><a href="/kb-docs/api/content/">k.content</a>, <a href="/kb-docs/api/database/">k.DB</a>, <a href="/kb-docs/api/commerce/commerce.html">k.commerce</a></td></tr><tr><td>Page Markdown or <code>llms.txt</code> output</td><td>Toggles and save paths on this page</td><td><a href="/kb-docs/templateEngine/page/">Page</a>, <a href="/kb-docs/templateEngine/view/">View</a>, <a href="/kb-docs/templateEngine/binding/">Template binding</a></td></tr><tr><td>JSON-LD fields from content or tables</td><td>Data source and mapping on this page</td><td><a href="./../content/content-types.html">Content Types</a>, <a href="./../database/">Database</a>, <a href="/kb-docs/templateEngine/k-data/">k-data</a></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Description</th></tr></thead><tbody><tr><td><a href="./">Settings overview</a></td><td>Settings menu and sub-routes</td></tr><tr><td><a href="./../operations/">Operations Center</a></td><td>Same-page entry for AI Service</td></tr><tr><td><a href="./basic/general.html">Basic Settings · General</a></td><td>Base URL and site info</td></tr><tr><td><a href="./../development/code.html">Development -&gt; Code</a></td><td>KScript / TypeScript code resources</td></tr><tr><td><a href="./../content/content-types.html">Content Types</a></td><td>JSON-LD content field sources</td></tr><tr><td><a href="./../database/">Database</a></td><td>JSON-LD database field sources</td></tr><tr><td><a href="/kb-docs/api/">KScript API</a></td><td>APIs available in AI function code</td></tr></tbody></table>',11))])}const S=s(l,[["render",g]]);export{v as __pageData,S as default};
